  {
   "id": "perpetual_confidentiality_undefined",
   "severity": "low",
   "message": "Confidentiality has no defined duration and no definition or exclusions for 'confidential information', which may make it harder to enforce.",
   "quote": "This applies during employment and after it ends."
  },
  {
   "id": "boilerplate_commercial_clauses_mismatch",
   "severity": "medium",
   "message": "The agreement contains B2B-style clauses (audit rights, insurance, warranties, mutual non-solicit of 'Personnel', assignment) that fit poorly with an individual employee. They create ambiguity and potentially unintended obligations, such as requiring the employee to carry insurance.",
   "quote": "Each Party must maintain commercial general liability and professional insurance at its own cost."
  },
  {
   "id": "employee_personnel_warranty",
   "severity": "low",
   "message": "The employee is made to confirm that 'its personnel' are qualified, which is inapplicable to an individual and is drafting noise.",
   "quote": "The Employee confirms that its personnel are suitably qualified."
  },
  {
   "id": "mutual_non_solicit_ambiguous",
   "severity": "low",
   "message": "The non-solicit refers to 'Personnel' involved in performing the Agreement, which is undefined and unclear for an employment context. It may be unenforceable or restrict Northwind unintentionally.",
   "quote": "During the term and for twelve months afterwards, neither Party may knowingly solicit for employment any Personnel of the other Party who were directly involved in the performance of this Agreement."
  },
  {
   "id": "no_notice_period_or_severance",
   "severity": "low",
   "message": "At-will termination with no notice period is flexible for Northwind but the agreement does not address post-termination matters such as return of property or notice.",
   "quote": "Employment is at-will. Either party may end it at any time."
  },
  {
   "id": "unsigned_and_notice_address_missing",
   "severity": "low",
   "message": "Notices clause refers to addresses 'set out below', but none are given, and signature lines are blank. Notice delivery and execution status are unclear.",
   "quote": "They must be delivered to the addresses set out below."
  }
